-- Function: public.fn_get_dashboard_organization_metrics
-- Backup generated on 2026-10-25 20:33:14

CREATE OR REPLACE FUNCTION public.fn_get_dashboard_organization_metrics(p_tenant_id uuid, p_organization_id uuid)  RETURNS TABLE(organization_id uuid, organization_name character varying, total_branches integer, active_branch_count integer, total_classrooms integer, total_children integer, total_teachers integer, children_experiencing_today integer, experiences_this_week integer, experiences_this_week_completed integer, experiences_this_week_upcoming integer, teacher_created_experiences integer, teacher_created_experiences_this_month integer)  LANGUAGE plpgsql AS $function$ BEGIN     RETURN QUERY     SELECT         o.id AS organization_id,         o.name::VARCHAR AS organization_name,         (SELECT COUNT(*)::INT FROM branches br WHERE br.organization_id = p_organization_id AND br.tenant_id = p_tenant_id) AS total_branches,         (SELECT COUNT(*)::INT FROM branches br WHERE br.organization_id = p_organization_id AND br.tenant_id = p_tenant_id AND br.is_active = true) AS active_branch_count,         (SELECT COUNT(*)::INT FROM classrooms cl JOIN branches br ON cl.branch_id = br.id WHERE br.organization_id = p_organization_id AND cl.tenant_id = p_tenant_id) AS total_classrooms,         (SELECT COUNT(*)::INT FROM children ch WHERE ch.tenant_id = p_tenant_id AND ch.is_active = true) AS total_children,         (SELECT COUNT(*)::INT FROM teachers tc WHERE tc.tenant_id = p_tenant_id AND tc.status != 'Inactive') AS total_teachers,         (SELECT COUNT(DISTINCT c.id)::INT FROM children c JOIN experience_schedules es ON c.classroom_id = es.classroom_id WHERE es.tenant_id = p_tenant_id AND es.scheduled_date = CURRENT_DATE) AS children_experiencing_today,         (SELECT COUNT(*)::INT FROM experience_schedules es WHERE es.tenant_id = p_tenant_id AND es.scheduled_date >= CURRENT_DATE - INTERVAL '7 days') AS experiences_this_week,         (SELECT COUNT(*)::INT FROM experience_schedules es WHERE es.tenant_id = p_tenant_id AND es.scheduled_date >= CURRENT_DATE - INTERVAL '7 days' AND es.status IN ('Completed', 'Finished')) AS experiences_this_week_completed,         (SELECT COUNT(*)::INT FROM experience_schedules es WHERE es.tenant_id = p_tenant_id AND es.scheduled_date >= CURRENT_DATE AND es.status NOT IN ('Completed', 'Finished')) AS experiences_this_week_upcoming,         (SELECT COUNT(*)::INT FROM experiences exp WHERE exp.tenant_id = p_tenant_id) AS teacher_created_experiences,         (SELECT COUNT(*)::INT FROM experiences exp WHERE exp.tenant_id = p_tenant_id AND exp.created_at >= date_trunc('month', CURRENT_DATE)) AS teacher_created_experiences_this_month     FROM organizations o     WHERE o.id = p_organization_id AND o.tenant_id = p_tenant_id; END; $function$ ;
